import SwiftUI

// MARK: - BrandMark / BrandLockup — the NOOP logo
//
// The mark is the arch of a lowercase n with a dot underneath it: your data, under its own roof. It is
// one flat shape in one colour (no tile, no gradient, no glow) and takes its colour from the call site,
// so it sits in the v2 chrome in ink like the rest of the furniture. The lockup sets the mark beside
// "noop" in Hanken Grotesk SemiBold, outlined, so it never waits on font loading and matches the README
// and the icons exactly.
//
// The path data is in BrandPaths.swift, generated by Tools/noop_brand.py along with the app icons, the
// Android drawables and the docs assets. Change the mark there, not here.

/// A brand path scaled uniformly into the rect it is given, centred (aspect-fit).
struct BrandShape: Shape {
    let source: Path
    let viewBox: CGRect

    static let mark = BrandShape(source: SVGPathParser.path(BrandPaths.mark), viewBox: BrandPaths.markViewBox)
    static let lockup = BrandShape(source: SVGPathParser.path(BrandPaths.lockup), viewBox: BrandPaths.lockupViewBox)

    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width / viewBox.width, rect.height / viewBox.height)
        guard scale > 0, scale.isFinite else { return Path() }
        let transform = CGAffineTransform(a: scale, b: 0, c: 0, d: scale,
                                          tx: rect.midX - viewBox.midX * scale,
                                          ty: rect.midY - viewBox.midY * scale)
        return source.applying(transform)
    }
}

/// The NOOP mark in a `size` × `size` frame (the drawn shape fills its 64-unit grid's 44-unit box).
/// Decorative: where the brand has to be announced, use `BrandLockup`, which carries the name.
public struct BrandMark: View {
    public var size: CGFloat
    public var color: Color

    public init(size: CGFloat = 120, color: Color = StrandPalette.textPrimary) {
        self.size = size
        self.color = color
    }

    public var body: some View {
        BrandShape.mark
            .fill(color)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

/// The mark + "noop" lockup at a fixed `height` (mark top to mark foot; the p's descender ends level
/// with the foot). Width follows from the lockup's proportions. Reads as "NOOP" to VoiceOver; callers
/// that replace a heading add `.accessibilityAddTraits(.isHeader)`.
public struct BrandLockup: View {
    public var height: CGFloat
    public var color: Color

    public init(height: CGFloat = 24, color: Color = StrandPalette.textPrimary) {
        self.height = height
        self.color = color
    }

    /// Width over height of the lockup, for callers that lay out around it.
    public static let aspectRatio = BrandPaths.lockupViewBox.width / BrandPaths.lockupViewBox.height

    public var body: some View {
        BrandShape.lockup
            .fill(color)
            .frame(width: height * Self.aspectRatio, height: height)
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(Text(verbatim: "NOOP"))
            .accessibilityAddTraits(.isImage)
    }
}

